import re
from datetime import date

INVALID = "INVALID"

_MONTHS = {}
for _i, _names in enumerate([
    ("january", "jan"), ("february", "feb", "febr"), ("march", "mar"),
    ("april", "apr"), ("may",), ("june", "jun"), ("july", "jul"),
    ("august", "aug"), ("september", "sep", "sept"), ("october", "oct"),
    ("november", "nov"), ("december", "dec"),
], start=1):
    for _n in _names:
        _MONTHS[_n] = _i

_WEEKDAY_PREFIX = re.compile(
    r"^(?:mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun)[a-z]*\.?,?\s+",
    re.IGNORECASE,
)


def _make(year, month, day):
    """Return an ISO date string for a real calendar date, else None."""
    try:
        return date(year, month, day).isoformat()
    except (ValueError, OverflowError):
        return None


def _month_number(name):
    return _MONTHS.get(name.lower().rstrip("."))


def parse(s: str) -> str:
    if not isinstance(s, str):
        return INVALID

    t = re.sub(r"\s+", " ", s.strip())
    if not t:
        return INVALID

    t = _WEEKDAY_PREFIX.sub("", t)

    # Year-first numeric: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    m = re.fullmatch(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})", t)
    if m:
        y, mo, d = (int(g) for g in m.groups())
        return _make(y, mo, d) or INVALID

    # Compact: YYYYMMDD
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
    if m:
        y, mo, d = (int(g) for g in m.groups())
        return _make(y, mo, d) or INVALID

    # Numeric with year last: a/b/YYYY (ambiguous order resolved as described)
    m = re.fullmatch(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})", t)
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if a > 12 and b <= 12:
            day, mo = a, b
        elif b > 12 and a <= 12:
            mo, day = a, b
        else:
            # Ambiguous: assume day-first.
            day, mo = a, b
        return _make(y, mo, day) or INVALID

    # Month name first: "March 5, 2021", "Mar 5th 2021", "Sept. 5 2021"
    m = re.fullmatch(
        r"([A-Za-z]+)\.?,?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})", t
    )
    if m:
        mo = _month_number(m.group(1))
        if mo is None:
            return INVALID
        return _make(int(m.group(3)), mo, int(m.group(2))) or INVALID

    # Day first with month name: "5 March 2021", "5th of Mar, 2021"
    m = re.fullmatch(
        r"(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?([A-Za-z]+)\.?,?\s+(\d{4})", t
    )
    if m:
        mo = _month_number(m.group(2))
        if mo is None:
            return INVALID
        return _make(int(m.group(3)), mo, int(m.group(1))) or INVALID

    return INVALID

import re
