    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_WEEKDAY_PREFIX = re.compile(
    r"^(?:mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun)[a-z]*\.?,?\s+",
    re.IGNORECASE | re.ASCII,
)
_ORD = r"(?:st|nd|rd|th)?"

# Year-first: 2024-03-05, 2024/3/5, 2024.03.05 (separator must be consistent)
_RE_YMD = re.compile(r"([0-9]{4})([-/.])([0-9]{1,2})\2([0-9]{1,2})", re.ASCII)
# Compact: 20240305
_RE_COMPACT = re.compile(r"([0-9]{4})([0-9]{2})([0-9]{2})", re.ASCII)
# Day-first numeric: 05/03/2024, 5-3-2024, 05.03.2024 (DD/MM/YYYY convention)
_RE_DMY = re.compile(r"([0-9]{1,2})([-/.])([0-9]{1,2})\2([0-9]{4})", re.ASCII)
# Day, month name, year: 31 Nov 2022, 31st-November-2022, 31 Nov. 2022
_RE_D_MON_Y = re.compile(
    r"([0-9]{1,2})" + _ORD + r"[ \-]?([A-Za-z]+)\.?,?[ \-]?([0-9]{4})",
    re.ASCII,
)
# Month name, day, year: Nov 31 2022, November 31st, 2022
_RE_MON_D_Y = re.compile(
    r"([A-Za-z]+)\.?[ \-]+([0-9]{1,2})" + _ORD + r",?[ \-]+([0-9]{4})",
    re.ASCII,
)


def _month_number(name: str):
    return _MONTHS.get(name.lower().rstrip("."))


def _build(y: int, m, d: int) -> str:
    if m is None:
        return "INVALID"
    try:
        return _dt.date(y, m, d).isoformat()
    except (ValueError, OverflowError):
        return "INVALID"


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    text = re.sub(r"\s+", " ", s).strip()
    if not text:
        return "INVALID"

    text = _WEEKDAY_PREFIX.sub("", text, count=1).strip()

    m = _RE_YMD.fullmatch(text)
    if m:
        return _build(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    m = _RE_COMPACT.fullmatch(text)
    if m:
        return _build(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    m = _RE_DMY.fullmatch(text)
    if m:
        return _build(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    m = _RE_D_MON_Y.fullmatch(text)
    if m:
        return _build(int(m.group(3)), _month_number(m.group(2)), int(m.group(1)))

    m = _RE_MON_D_Y.fullmatch(text)
    if m:
        return _build(int(m.group(3)), _month_number(m.group(1)), int(m.group(2)))

    return "INVALID"

import re
import datetime

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_ORD = r"(?:st|nd|rd|th)?"


def _build(y: int, m: int, d: int) -> str:
    try:
        return datetime.date(y, m, d).isoformat()
    except (ValueError, OverflowError):
        return "INVALID"


def _month(token: str):
    return _MONTHS.get(token.rstrip(".").lower())


def _iso(s: str):
    m = re.fullmatch(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})", s)
    if m:
        return _build(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    return None


def _day_month_year(s: str):
    # e.g. "5th March 2024", "5 March, 2024", "05-mar-2024", "5th of March 2024"
    m = re.fullmatch(
        r"(\d{1,2})" + _ORD + r"[\s\-/.,]*(?:of\s+)?([a-z]+\.?)[\s\-/.,]*(\d{4})",
        s,
    )
    if not m:
        return None
    mon = _month(m.group(2))
    if mon is None:
        return "INVALID"
    return _build(int(m.group(3)), mon, int(m.group(1)))


def _month_day_year(s: str):
    # e.g. "June 31, 2021", "March 5th 2024", "Feb. 29 2023"
    m = re.fullmatch(
        r"([a-z]+\.?)[\s\-/.]*(\d{1,2})" + _ORD + r"[\s,\-/.]*(\d{4})",
        s,
    )
    if not m:
        return None
    mon = _month(m.group(1))
    if mon is None:
        return "INVALID"
    return _build(int(m.group(3)), mon, int(m.group(2)))


def _numeric(s: str):
    # e.g. "03/05/2024", "13/02/2024", "02-13-2024"
    m = re.fullmatch(r"(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})", s)
    if not m:
        return None
    a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
    if a > 12 and b <= 12:
        day, month = a, b
    elif b > 12 and a <= 12:
        month, day = a, b
    else:
        # Both parts <= 12: assume day-first.
        day, month = a, b
    return _build(y, month, day)


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"
    t = re.sub(r"\s+", " ", s.strip()).lower()
    if not t:
        return "INVALID"
    # Drop an optional leading weekday name, e.g. "Tuesday, " or "Tue "
    t = re.sub(
        r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
        r"|mon|tues|tue|wed|thurs|thur|thu|fri|sat|sun)\.?,?\s+",
        "",
        t,
    )

    for handler in (_iso, _day_month_year, _month_day_year, _numeric):
        result = handler(t)
        if result is not None:
            return result
    return "INVALID"

import re
from datetime import date

# Year-first numeric dates (ISO-like). The same separator must be used on both sides
# ("-", "/", or "."). Month and day may be unpadded (1-2 digits). Only [0-9] is matched
# so that non-ASCII digit characters are not accepted.
_YMD_PATTERN = re.compile(r"([0-9]{4})([-/.])([0-9]{1,2})\2([0-9]{1,2})")

# Day-first numeric dates, e.g. "05/03/2024" -> 2024-03-05 and "31/12/1999" -> 1999-12-31.
# Separator must match on both sides ("-", "/", or "."). Day and month may be unpadded.
_DMY_PATTERN = re.compile(r"([0-9]{1,2})([-/.])([0-9]{1,2})\2([0-9]{4})")

# Day-first with optional ordinal suffix and English month name, e.g. "22nd Feb 1900".
_NAMED_DMY_PATTERN = re.compile(
    r"([0-9]{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\.?,?\s+([0-9]{4})"
)

# Month-first with optional ordinal suffix and English month name, e.g. "Sept 22, 2021"
# or "February 3rd 2020".
_NAMED_MDY_PATTERN = re.compile(
    r"([A-Za-z]+)\.?\s+([0-9]{1,2})(?:st|nd|rd|th)?,?\s+([0-9]{4})"
)

# Optional leading weekday name, e.g. "Tuesday, " in "Tuesday, March 5, 2024".
# Longer alternatives come first so "Tuesday" is consumed whole rather than as "Tue".
_WEEKDAY_PREFIX = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues|tue|wed|thurs|thur|thu|fri|sat|sun)\.?,?\s+",
    re.IGNORECASE,
)

_MONTHS = {
    "jan": 1, "january": 1, "feb": 2, "february": 2, "mar": 3, "march": 3,
    "apr": 4, "april": 4, "may": 5, "jun": 6, "june": 6, "jul": 7, "july": 7,
    "aug": 8, "august": 8, "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10, "nov": 11, "november": 11, "dec": 12, "december": 12,
}


def _to_iso(year: int, month: int, day: int) -> str:
    """Return ISO date string, or 'INVALID' if the components do not form a real date."""
    try:
        # date() rejects impossible values such as month 0, day 31 in April,
        # and Feb 29 in non-leap years (e.g. 1900).
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def _month_number(name: str):
    return _MONTHS.get(name.lower())


def _parse_named_dmy(s: str):
    n = _NAMED_DMY_PATTERN.fullmatch(s)
    if n is None:
        return None
    day_s, mon_s, year_s = n.groups()
    month = _month_number(mon_s)
    if month is None:
        return "INVALID"
    return _to_iso(int(year_s), month, int(day_s))


def _parse_named_mdy(s: str):
    n = _NAMED_MDY_PATTERN.fullmatch(s)
    if n is None:
        return None
    mon_s, day_s, year_s = n.groups()
    month = _month_number(mon_s)
    if month is None:
        return "INVALID"
    return _to_iso(int(year_s), month, int(day_s))


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    s = s.strip()

    # Drop an optional leading weekday name before parsing the date itself
    s = _WEEKDAY_PREFIX.sub("", s, count=1)

    # Year-first numeric: YYYY-MM-DD, YYYY/MM/DD, or YYYY.MM.DD
    m = _YMD_PATTERN.fullmatch(s)
    if m is not None:
        year_s, _sep, month_s, day_s = m.groups()
        return _to_iso(int(year_s), int(month_s), int(day_s))

    # Day-first numeric: DD/MM/YYYY (also DD-MM-YYYY, DD.MM.YYYY)
    m = _DMY_PATTERN.fullmatch(s)
    if m is not None:
        day_s, _sep, month_s, year_s = m.groups()
        return _to_iso(int(year_s), int(month_s), int(day_s))

    # Named month, day-first: "22 Feb 1900", "22nd September, 2021"
    result = _parse_named_dmy(s)
    if result is not None:
        return result

    # Named month, month-first: "Sept 22, 2021", "February 3rd 2020"
    result = _parse_named_mdy(s)
    if result is not None:
        return result

    return "INVALID"
